SELECT FINPROD_MARKET_ID id, FINPROD_ABBR text, FINPROD_TYPE2, FINPROD_TYPE FROM FIN_PRODUCT WHERE (PROFIT_TYPE=#{PROFITTYPE_VALUE_02} OR PROFIT_TYPE IS NULL)
AND FINPROD_TYPE in (#{TYPE_F17}) AND FINPROD_MARKET_ID IS NOT NULL
AND (FINPROD_MARKET_ID like concat(concat('%', #{search,jdbcType=VARCHAR}),'%'))
AND FINPROD_MARKET_ID = #{initValue}
AND FINPROD_MARKET_ID = #{finprodMarketId}

		SELECT
		       FINPROD_ID finprodId,
		       VAL_DATE valDate,
		       VALUATION netValue
        FROM
               FIN_PRODUCT_VALUATION
        WHERE
               FINPROD_ID=#{finprodId}
               /** modify by yanya on 20210329 使用估值侧类型进行过滤**/

                AND FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
               AND to_char(VAL_DATE,'yyyy-MM-dd') = #{valDate}
